```csharp
public int LoggingQueueCapacity
{
    get => _loggingQueueCapacity;
    set
    {
        if (value <= 0)
            throw new ArgumentOutOfRangeException(nameof(value), "Capacity must be > 0.");
        _loggingQueueCapacity = value;
    }
}
